```java
class Money { int amount; public boolean equals(Object o) {
  return o instanceof Money m && amount == m.amount;
}}
class Voucher extends Money { String code; public boolean equals(Object o) {
  return o instanceof Voucher v && super.equals(v) && code.equals(v.code);
}}
```

